import { motion } from "framer-motion";

type Tab = "overview" | "investments" | "debt" | "portfolio" | "telemetry";

const TABS: Array<{ id: Tab; label: string }> = [
  { id: "overview", label: "OVERVIEW" },
  { id: "investments", label: "INVESTMENTS" },
  { id: "debt", label: "DEBT" },
  { id: "portfolio", label: "PORTFOLIO" },
  { id: "telemetry", label: "TELEMETRY" },
];

/** The Finance rebuild - real money, legibility over flourish. The left
    rail is the SpeedoNav; the TELEMETRY tab carries the blueprint blocks
    and standard widgets (seed data for now - PLANNED_WORK.md P8). */
export default function Home() {
  const [tab, setTab] = useState<Tab>("overview");

  return (
    <div className="flex min-h-screen flex-col">
      <header className="page-header border-b border-line/40 bg-transparent">
        <div className="header-pad mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-3 px-6 py-4">
          <h1 className="page-title font-mono text-2xl font-black tracking-tight grad-text-flow">
            FINANCE{" "}
            <span className="font-light text-bone">
              overview · investments · debt · portfolio · telemetry
            </span>
          </h1>
        </div>
      </header>

      <main className="page-main mx-auto w-full max-w-6xl flex-1 px-6 py-6">
        <div className="grid-main grid grid-cols-[64px_1fr_300px] gap-6">
          <SpeedoNav
            items={TABS}
            tab={tab}
            onSelect={(id) => setTab(id as Tab)}
          />
          <motion.div
            key={tab}
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
            className="flex flex-col gap-6 [perspective:1200px]"
          >
            {tab === "overview" && <OverviewPanel />}
            {tab === "investments" && <InvestmentsPanel />}
            {tab === "debt" && <DebtPanel />}
            {tab === "portfolio" && <PortfolioPanel />}
            {tab === "telemetry" && <TelemetryPanel />}
          </motion.div>
          <div className="rail flex flex-col gap-6">
            <ActivityRail />
          </div>
        </div>
      </main>

      <footer className="mx-auto w-full max-w-6xl px-6 pb-6 pt-2">
        <p className="num text-[10px] leading-relaxed text-dim">
          every figure traces to server_for_finance.py&apos;s own endpoints (C4) · never a buy/sell
