          {" · TELEMETRY tab runs on seed data until the live wiring lands (PLANNED_WORK.md P8)"}
          {" · events stream from Shared_By_All_Screens/Trace_Ledger via /api/finance/live"}
        </p>
      </footer>
    </div>
  );
}
